import Foundation

struct PlaneCity: Equatable {
    enum Kind: Character, Equatable {
        case capital = "c"
        case stateCapital = "s"
        case city = "m"
    }

    let name: String
    let country: String
    let latitude: Double
    let longitude: Double
    var kind: Kind = .capital
    var hub = false

    var point: PlaneVector {
        PlaneVector(latitude: latitude, longitude: longitude)
    }
}

enum PlaneAtlas {
    static let maximumStep = 2.0 * .pi / 180

    static let cities: [PlaneCity] = cityData.split(separator: "\n").compactMap(city)

    static let land: [[PlaneVector]] = landData.split(separator: "\n").map(ring).filter { $0.count > 2 }

    static func isPolar(_ ring: [PlaneVector]) -> Bool {
        guard !ring.isEmpty else { return false }
        return ring.reduce(0) { $0 + $1.z } / Double(ring.count) < -0.9
    }

    static func city(_ line: Substring) -> PlaneCity? {
        let fields = line.split(separator: "|", omittingEmptySubsequences: false)
        guard fields.count == 5,
              !fields[0].isEmpty,
              fields[2].count == 1,
              let letter = fields[2].first,
              let kind = letter.lowercased().first.flatMap(PlaneCity.Kind.init),
              let latitude = Double(fields[3]),
              let longitude = Double(fields[4]),
              abs(latitude) <= 90,
              abs(longitude) <= 180
        else { return nil }
        return PlaneCity(name: String(fields[0]), country: String(fields[1]), latitude: latitude, longitude: longitude, kind: kind, hub: letter.isUppercase)
    }

    static func ring(_ line: Substring) -> [PlaneVector] {
        let corners = line.split(separator: " ").compactMap { pair -> PlaneVector? in
            let values = pair.split(separator: ",")
            guard values.count == 2, let longitude = Double(values[0]), let latitude = Double(values[1]) else { return nil }
            return PlaneVector(latitude: latitude / 10, longitude: longitude / 10)
        }
        guard corners.count > 2 else { return corners }
        var points: [PlaneVector] = []
        for (index, corner) in corners.enumerated() {
            let next = corners[(index + 1) % corners.count]
            let steps = max(1, Int((corner.angle(to: next) / maximumStep).rounded(.up)))
            for step in 0..<steps {
                points.append(PlaneVector.slerp(corner, next, Double(step) / Double(steps)))
            }
        }
        return points
    }

